// Pull name + domain from Apollo company-search response
const orgs = $input.first().json.organizations || [];
if (!orgs.length) return [{ json: { _skip: true, error: 'Apollo returned 0 companies for this search' } }];

return orgs
  .filter(o => o.primary_domain || o.website_url)
  .map(o => {
    let domain = o.primary_domain;
    if (!domain && o.website_url) {
      domain = o.website_url.replace(/https?:\/\//, '').split('/')[0].replace(/^www\./, '');
    }
    return {
      json: {
        company_name:    o.name,
        company_domain:  domain.toLowerCase().trim(),
        apollo_org_id:   o.id || '',
        org_linkedin:    o.linkedin_url || '',
        status:          'pending'
      }
    };
  });

const TIERS = [
  { tier: 5, label: 'Purchasing Manager',   patterns: [/purchasing\s*manager/i,/head\s*of\s*purchasing/i,/director\s*of\s*purchasing/i,/vp.*purchasing/i] },
  { tier: 4, label: 'Procurement \/ Buyer',  patterns: [/procurement/i,/\bbuyer\b/i,/senior\s*buyer/i,/sourcing/i,/supply\s*chain/i] },
  { tier: 3, label: 'Operations Manager',   patterns: [/operations\s*manager/i,/ops\s*manager/i,/operations\s*director/i,/fulfillment/i,/warehouse\s*manager/i,/production\s*manager/i] },
  { tier: 2, label: 'General Manager \/ MD', patterns: [/general\s*manager/i,/\bgm\b/i,/managing\s*director/i] },
  { tier: 1, label: 'Owner \/ Founder',     patterns: [/\bfounder\b/i,/\bowner\b/i,/\bceo\b/i,/\bpresident\b/i,/^director$/i] }
];

function score(title) {
  if (!title) return { tier: 0, label: 'No match' };
  for (const t of TIERS) { if (t.patterns.some(p => p.test(title))) return t; }
  return { tier: 0, label: 'No match' };
}

const apolloResp = $input.item.json;
const people     = apolloResp.people || [];
const org        = ($('Apollo: Find Organization').item.json.organizations || [])[0] || {};
const row        = $('Read Pending Rows').item.json;

const scored = people
  .map(p => ({ ...p, _score: score(p.title) }))
  .filter(p => p._score.tier > 0)
  .sort((a, b) => b._score.tier - a._score.tier)
  .slice(0, 2);

const base = {
  company_name:  row.company_name,
  company_domain: row.company_domain,
  apollo_org_id: org.id || '',
  org_industry:  (org.industries || []).join(', '),
  org_headcount: org.estimated_num_employees || '',
  org_location:  [org.city, org.state, org.country].filter(Boolean).join(', '),
  org_linkedin:  org.linkedin_url || ''
};

if (!scored.length) {
  return { json: { ...base, found: false, error_reason: 'No contact matched persona tiers 1-5' } };
}

const c1 = scored[0];
const c2 = scored[1] || null;

return { json: {
  ...base,
  found: true,
  contact_id:         c1.id,
  contact_first_name: c1.first_name || '',
  contact_last_name:  c1.last_name || '',
  contact_title:      c1.title || '',
  contact_linkedin:   c1.linkedin_url || '',
  persona_tier:       c1._score.tier,
  persona_label:      c1._score.label,
  // Second contact (optional)
  contact2_id:         c2 ? c2.id : '',
  contact2_first_name: c2 ? c2.first_name || '' : '',
  contact2_last_name:  c2 ? c2.last_name || '' : '',
  contact2_title:      c2 ? c2.title || '' : '',
  contact2_tier:       c2 ? c2._score.tier : '',
  contact2_label:      c2 ? c2._score.label : ''
}};

// Phantombuster returns JSON output with scraped profiles
const raw = $input.item.json.output || '[]';
let profiles = [];
try { profiles = JSON.parse(raw); } catch(e) {}

const row = $('Read Pending Rows').item.json;
const pick = $('Pick Best 1-2 Contacts').item.json;

if (!profiles.length || !profiles[0]) {
  return { json: { found: false, company_name: row.company_name, company_domain: row.company_domain,
    error_reason: 'Phantombuster returned no LinkedIn profiles for this company' }};
}

// Grab first valid profile that has a name
const p = profiles.find(x => x.firstName || x.first_name) || profiles[0];
return { json: {
  found:              !!(p.email || p.mailAddress),
  company_name:       row.company_name,
  company_domain:     row.company_domain,
  apollo_org_id:      pick.apollo_org_id,
  org_industry:       pick.org_industry,
  org_headcount:      pick.org_headcount,
  org_location:       pick.org_location,
  contact_first_name: p.firstName || p.first_name || '',
  contact_last_name:  p.lastName  || p.last_name  || '',
  contact_title:      p.title     || p.jobTitle   || '',
  contact_linkedin:   p.profileUrl || '',
  contact_email:      p.email || p.mailAddress || '',
  persona_tier:       pick.persona_tier,
  persona_label:      pick.persona_label
}};
